+            PipeBarrier<PIPE_MTE3>();
+        }
+        if (loopIdx < loopTimes - 1) {
+            SetFlag<HardEvent::MTE3_MTE2>(constInfo.deterConstInfo.eventIDMte3ToMte2);
+        }
+    }
